//! CI token exchange end to end (G3.8b): the server binary with a `[ci]`
//! section trusting a recorded JWKS (`tests/fixtures/ci/`, regenerated by
//! `gen.py` with throwaway keys), served over loopback HTTP so the
//! fetch-and-refresh path runs too.
//!
//! A recorded GitHub Actions token is exchanged for a graft token; that
//! token attests both of `main`'s required checks (decision D6) on a draft,
//! after which an `attested` land succeeds. A token for another repository
//! is refused, at the exchange or at the attest.

mod common;

use std::collections::BTreeMap;
use std::io::{BufRead as _, BufReader, Write as _};
use std::net::TcpListener;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};

use common::{Auth, Server, Site, api};
use graft_model::ChangesetId;
use graft_proto::pb;
use graft_proto::types::{Attest, Land, Landed, MergeMode};
use graft_proto::{ApiError, PROTOCOL_VERSION, VERSION_HEADER};
use tonic::service::interceptor::InterceptedService;
use tonic::transport::Channel;

const AUDIENCE: &str = "https://graft.e2e.test";
const WORKFLOW: &str = "o/graft-ci/.github/workflows/graft-pre-land.yml@refs/heads/main";

fn token(name: &str) -> String {
    let all: BTreeMap<String, String> =
        serde_json::from_str(include_str!("fixtures/ci/tokens.json")).expect("tokens");
    all.get(name)
        .unwrap_or_else(|| panic!("no fixture {name}"))
        .clone()
}

/// A loopback HTTP server answering every request with the current body.
struct JwksServer {
    url: String,
    body: Arc<Mutex<String>>,
    hits: Arc<AtomicUsize>,
}

impl JwksServer {
    fn start(body: &str) -> Self {
        let listener = TcpListener::bind("127.0.0.1:0").expect("bind");
        let url = format!("http://{}/jwks", listener.local_addr().expect("addr"));
        let body = Arc::new(Mutex::new(body.to_owned()));
        let hits = Arc::new(AtomicUsize::new(0));
        let (b, h) = (body.clone(), hits.clone());
        std::thread::spawn(move || {
            for stream in listener.incoming() {
                let Ok(mut stream) = stream else { continue };
                let mut reader = BufReader::new(stream.try_clone().expect("clone"));
                let mut line = String::new();
                while reader.read_line(&mut line).is_ok_and(|n| n > 2) {
                    line.clear();
                }
                h.fetch_add(1, Ordering::SeqCst);
                let text = b.lock().expect("body").clone();
                let _ = write!(
                    stream,
                    "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{text}",
                    text.len()
                );
            }
        });
        Self { url, body, hits }
    }

    fn serve(&self, body: &str) {
        *self.body.lock().expect("body") = body.to_owned();
    }
}

/// The commit the recorded tokens say their job ran on (`gen.py`).
const SHA: &str = "1f2e3d4c5b6a79881f2e3d4c5b6a79881f2e3d4c";

/// The `[ci]` section: `o/app` bound to graft repo `r` (attest, so pinned),
/// `o/other` to `other`, `o/reader` to `r` for reads only. The recorded
/// tokens were issued in 2025 and expire in 2096, so the lifetime limit is
/// raised for them; nothing else is relaxed. `commit_map` is the static
/// changeset-to-commit map file.
fn ci_config(keys: &str, commit_map: &std::path::Path) -> String {
    format!(
        r#"
[ci]
max_token_ttl_s = 600
commit_map_file = "{}"

[[ci.issuers]]
provider = "github"
issuer = "https://token.actions.githubusercontent.com"
audience = "{AUDIENCE}"
{keys}
max_lifetime_s = 3000000000

[[ci.bindings]]
provider = "github"
ci_repo = "o/app"
repo_id = "101"
graft_repo = "r"
refs = ["refs/heads/graft/"]
workflows = ["{WORKFLOW}"]
scopes = ["repo:r:read", "repo:r:attest"]

[[ci.bindings]]
provider = "github"
ci_repo = "o/other"
repo_id = "102"
graft_repo = "other"
refs = ["refs/heads/graft/"]
workflows = ["{WORKFLOW}"]
scopes = ["repo:other:read", "repo:other:attest"]

[[ci.bindings]]
provider = "github"
ci_repo = "o/reader"
repo_id = "104"
graft_repo = "r"
workflows = ["{WORKFLOW}"]
scopes = ["repo:r:read"]
"#,
        commit_map.display()
    )
}

type CiClient = pb::ci_service_client::CiServiceClient<InterceptedService<Channel, Auth>>;

async fn ci_client(server: &Server, auth: Auth) -> CiClient {
    pb::ci_service_client::CiServiceClient::with_interceptor(server.channel().await, auth)
}

async fn exchange(server: &Server, jwt: &str) -> Result<String, ApiError> {
    exchange_pinned(server, jwt, None).await
}

async fn exchange_pinned(
    server: &Server,
    jwt: &str,
    pin: Option<ChangesetId>,
) -> Result<String, ApiError> {
    ci_client(server, Auth::new(None))
        .await
        .exchange_ci_token(pb::ExchangeCiTokenRequest {
            ci_token: jwt.to_owned(),
            changeset: pin.map(|c| c.to_string()),
        })
        .await
        .map(|r| r.into_inner().token)
        .map_err(api)
}

/// `r` with `main` at a root changeset, and a draft on top of it.
async fn repo_with_draft(site: &Site, server: &Server) -> ChangesetId {
    let admin = site.mint(&["repo:r:admin"]);
    let mut c = server.clients(Some(&admin)).await;
    c.create_repo("r").await.expect("create");
    let before = BTreeMap::new();
    let mut files = BTreeMap::from([("README.md".to_owned(), b"hello\n".to_vec())]);
    let root = c.commit("r", None, &before, &files, 0).await.expect("root");
    c.set_line("r", "main", root.id).await.expect("main");
    let snapshot = files.clone();
    files.insert("README.md".to_owned(), b"hello, CI\n".to_vec());
    c.commit("r", Some(root.id), &snapshot, &files, 1)
        .await
        .expect("draft")
        .id
}

async fn attest(
    server: &Server,
    token: &str,
    changeset: ChangesetId,
    check: &str,
) -> Result<(), ApiError> {
    server
        .clients(Some(token))
        .await
        .repo
        .attest(pb::AttestRequest::from(Attest {
            repo: "r".into(),
            changeset,
            check: check.into(),
            passed: true,
            url: "https://github.example/o/app/actions/runs/1".into(),
        }))
        .await
        .map(|_| ())
        .map_err(api)
}

async fn land(server: &Server, token: &str, head: ChangesetId) -> Result<Landed, ApiError> {
    let landed = server
        .clients(Some(token))
        .await
        .repo
        .land(pb::LandRequest::from(Land {
            repo: "r".into(),
            head,
            line: "main".into(),
            squash: false,
            merge: MergeMode::File,
            deadline_ms: None,
        }))
        .await
        .map_err(api)?
        .into_inner();
    Ok(Landed::try_from(landed).expect("valid landed"))
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn an_exchanged_ci_token_attests_and_the_attested_land_succeeds() {
    let jwks = JwksServer::start(include_str!("fixtures/ci/jwks.json"));
    let maps = graft_testkit::crash::TempDir::new("server-ci-e2e-map");
    let commit_map = maps.path().join("commits");
    let site = Site::new(
        "server-ci-e2e",
        &ci_config(&format!("jwks_url = \"{}\"", jwks.url), &commit_map),
    );
    let server = site.start();
    assert!(
        jwks.hits.load(Ordering::SeqCst) >= 1,
        "keys fetched at start-up"
    );
    let draft = repo_with_draft(&site, &server).await;
    let lander = site.mint(&["repo:r:write", "repo:r:land:main"]);
    let pinned = |name: &'static str| {
        let server = &server;
        async move { exchange_pinned(server, &token(name), Some(draft)).await }
    };

    // Before CI attests, D6 refuses the land.
    assert!(
        matches!(
            land(&server, &lander, draft).await,
            Err(ApiError::Rejected { .. })
        ),
        "an unattested land is rejected"
    );

    // A binding that can attest mints only pinned tokens, and only once the
    // job's commit is known to be the draft's export: refused (fail closed)
    // until the map says so.
    assert!(matches!(
        exchange(&server, &token("ok")).await,
        Err(ApiError::PermissionDenied { .. })
    ));
    assert!(matches!(
        pinned("ok").await,
        Err(ApiError::PermissionDenied { .. })
    ));
    std::fs::write(&commit_map, format!("{draft} {SHA}\n")).expect("write commit map");
    let ci = pinned("ok").await.expect("exchange");
    assert!(ci.starts_with("v4.public."), "a graft token");
    // A job on another commit cannot attest this draft.
    assert!(matches!(
        pinned("other_commit").await,
        Err(ApiError::PermissionDenied { .. })
    ));
    // A read-only binding needs no pin.
    exchange(&server, &token("reader"))
        .await
        .expect("read token");

    // A token for another repository: refused at the exchange when the CI
    // repository is not bound, and at the attest when it is bound to
    // another graft repository.
    assert!(matches!(
        pinned("unbound").await,
        Err(ApiError::PermissionDenied { .. })
    ));
    let other = pinned("other_repo").await.expect("bound to other");
    assert!(matches!(
        attest(&server, &other, draft, "ci/build").await,
        Err(ApiError::PermissionDenied { .. })
    ));
    // A workflow the binding does not pin, and the wrong audience.
    assert!(matches!(
        pinned("own_workflow").await,
        Err(ApiError::PermissionDenied { .. })
    ));
    assert!(matches!(
        pinned("wrong_aud").await,
        Err(ApiError::Unauthenticated)
    ));

    // CI attests both checks; the land now succeeds.
    for check in ["ci/build", "ci/test"] {
        attest(&server, &ci, draft, check).await.expect("attest");
    }
    match land(&server, &lander, draft).await.expect("land") {
        Landed::Landed { landed, .. } => assert_eq!(landed, draft),
        other => panic!("not landed: {other:?}"),
    }

    // The CI token cannot land, even though it can attest.
    assert!(matches!(
        land(&server, &ci, draft).await,
        Err(ApiError::PermissionDenied { .. })
    ));
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn an_unknown_key_refetches_the_key_set_once_a_minute() {
    let jwks = JwksServer::start(include_str!("fixtures/ci/jwks.json"));
    let site = Site::new(
        "server-ci-rotate",
        &ci_config(
            &format!("jwks_url = \"{}\"", jwks.url),
            std::path::Path::new("/nonexistent"),
        ),
    );
    let server = site.start();
    let start_hits = jwks.hits.load(Ordering::SeqCst);

    // The issuer rotates: a token signed by the new key makes the server
    // refetch, and then it verifies: what refuses it now is only the
    // missing pin (`PermissionDenied`), not the key (`Unauthenticated`).
    jwks.serve(include_str!("fixtures/ci/jwks-rotated.json"));
    assert!(matches!(
        exchange(&server, &token("rotated")).await,
        Err(ApiError::PermissionDenied { .. })
    ));
    assert_eq!(jwks.hits.load(Ordering::SeqCst), start_hits + 1);

    // Unknown key ids within the minute cost no further fetch.
    let mut header = serde_json::json!({"alg": "RS256", "typ": "JWT", "kid": "nope"}).to_string();
    header = base64_url(header.as_bytes());
    let ok = token("ok");
    let (_, rest) = ok.split_once('.').expect("a JWT");
    let unknown = format!("{header}.{rest}");
    for _ in 0..3 {
        assert!(matches!(
            exchange(&server, &unknown).await,
            Err(ApiError::Unauthenticated)
        ));
    }
    assert_eq!(jwks.hits.load(Ordering::SeqCst), start_hits + 1);
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_exchange_binds_the_protocol_and_is_off_without_an_issuer() {
    let dir = graft_testkit::crash::TempDir::new("server-ci-file");
    let path = dir.path().join("jwks.json");
    std::fs::write(&path, include_str!("fixtures/ci/jwks.json")).expect("write jwks");
    let site = Site::new(
        "server-ci-file",
        &ci_config(
            &format!("jwks_file = \"{}\"", path.display()),
            &dir.path().join("no-map"),
        ),
    );
    let server = site.start();

    // Keys from a file work the same.
    exchange(&server, &token("reader")).await.expect("exchange");

    // No protocol header: refused before the token is looked at.
    let refused = ci_client(&server, Auth::new(None).without_version())
        .await
        .exchange_ci_token(pb::ExchangeCiTokenRequest {
            ci_token: token("reader"),
            changeset: None,
        })
        .await
        .expect_err("no version");
    assert!(matches!(
        api(refused),
        ApiError::IncompatibleProtocol { .. }
    ));

    // A bearer token is not a CI token.
    let graft = site.mint(&["repo:r:read"]);
    assert!(matches!(
        exchange(&server, &graft).await,
        Err(ApiError::Unauthenticated)
    ));

    // The answer carries the protocol version like every other.
    let answer = ci_client(&server, Auth::new(None))
        .await
        .exchange_ci_token(pb::ExchangeCiTokenRequest {
            ci_token: token("reader"),
            changeset: None,
        })
        .await
        .expect("exchange");
    assert_eq!(
        answer
            .metadata()
            .get(VERSION_HEADER)
            .and_then(|v| v.to_str().ok()),
        Some(PROTOCOL_VERSION.to_string().as_str())
    );

    // With no `[ci]` section the exchange is off.
    let plain = Site::new("server-ci-off", "").start();
    assert!(matches!(
        exchange(&plain, &token("reader")).await,
        Err(ApiError::Unauthenticated)
    ));
}

fn base64_url(raw: &[u8]) -> String {
    const ALPHABET: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    let mut out = String::new();
    for chunk in raw.chunks(3) {
        let n = chunk
            .iter()
            .enumerate()
            .fold(0u32, |acc, (i, b)| acc | u32::from(*b) << (16 - 8 * i));
        for i in 0..=chunk.len() {
            out.push(ALPHABET[(n >> (18 - 6 * i) & 63) as usize] as char);
        }
    }
    out
}
